(async () => {
  const root = document.querySelector('[data-flow]');
  const out = {nodes: root.querySelectorAll('[data-flow-step]').length};
  const first = root.querySelector('[data-flow-panel].is-active');
  out.firstPanel = first ? first.querySelector('.flow__title').textContent : null;
  out.fillStart = root.querySelector('.flow__rail-fill').style.width;
  // jump to step 3
  root.querySelectorAll('[data-flow-step]')[2].click();
  await new Promise(r => setTimeout(r, 600));
  const active = root.querySelector('[data-flow-panel].is-active');
  out.afterClick = active ? active.querySelector('.flow__title').textContent : null;
  out.fillAfter = root.querySelector('.flow__rail-fill').style.width;
  out.count = root.querySelector('[data-flow-count]').textContent;
  out.shot = root.querySelector('[data-flow-shot].is-active img').getAttribute('src');
  out.specItems = [...document.querySelectorAll('.specbar__k')].map(e => e.textContent);
  return out;
})()
